CustomField.formula:
HYPERLINK(
/** 🔗 The Link path is set here 🔗 **/
'/'&BlankValue(Contact_1__c,BlankValue(Lead_1__c,BlankValue(Account__c,CreatedById))), 

/** 🙋🏽‍♀️ Display Primary Contact Name 🙋🏽‍♀️ **/
IF(Not(IsBlank(Contact_1__c)),Contact_1__r.FirstName&" "&Contact_1__r.LastName,

/** 🙋‍♂️ Display Primary Lead Name 🙋‍♂️ **/
IF(Not(IsBlank(Lead_1__c)),Lead_1__r.FirstName&" "&Lead_1__r.LastName,

/** 🏢 Display Account Name 🏢 **/
IF(Not(IsBlank(Account__c)),Account__r.Name,

CreatedBy.FirstName+" "+CreatedBy.LastName))),

'_self')
